contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 tokenId, uint256 points, uint256 extraTokenId) public {
        c.adjustAdminAccess(address(this), true);

        uint256 oldTotal = c.totalPoints();
        uint256 oldPoints = c.fighterPoints(tokenId);
        uint256 oldExtra = c.fighterPoints(extraTokenId);

        c.addPoints(tokenId, points);

        uint256[] memory winners = new uint256[](c.winnersPerPeriod());
        for (uint256 i = 0; i < winners.length; i++) {
            winners[i] = tokenId;
        }

        c.pickWinner(winners);

        uint256 newTotal = c.totalPoints();
        uint256 newPoints = c.fighterPoints(tokenId);
        uint256 newExtra = c.fighterPoints(extraTokenId);

        assert(newTotal == oldTotal + oldExtra + points - oldPoints - oldPoints - oldExtra
            && newPoints == 0
            && newExtra == oldExtra);
    }
}

