        uint256 oldTotal = c.totalPoints();

        uint256[] memory winners = new uint256[](winnersPerPeriod);
        winners[0] = tokenA;
        winners[1] = tokenB;

        c.pickWinner(winners);

        uint256 newTotal = c.totalPoints();
        uint256 newPointsA = c.fighterPoints(tokenA);
