contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 tokenId, uint256 points, uint256 maxId) public payable {
        require(address(this).balance >= 0);
        uint256 beforeFighterPoints = c.fighterPoints(tokenId);
        uint256 beforeTotalPoints = c.totalPoints();
        bool reverted;
        try c.addPoints(tokenId, points) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterFighterPoints = c.fighterPoints(tokenId);
        uint256 afterTotalPoints = c.totalPoints();
        uint256[] memory pts = c.getFighterPoints(maxId);
        if (!reverted) {
            assert(afterFighterPoints == beforeFighterPoints + points && afterTotalPoints == beforeTotalPoints + points);
        } else {
            assert(afterFighterPoints == beforeFighterPoints && afterTotalPoints == beforeTotalPoints);
        }
        assert(pts.length == 1);
    }

    receive() external payable {}
}

