contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 winnerTokenId) public payable {
        uint256 beforeRoundId = c.roundId();
        uint256 beforeWinnersPerPeriod = c.winnersPerPeriod();
        require(beforeWinnersPerPeriod == 1, "setup assumption");
        uint256[] memory winners = new uint256[](1);
        winners[0] = winnerTokenId;

        bool reverted;
        try c.pickWinner(winners) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            assert(c.roundId() == beforeRoundId + 1);
            assert(c.isSelectionComplete(beforeRoundId));
            assert(c.winnerAddresses(beforeRoundId, 0) == c.ownerOf(winnerTokenId));
        } else {
            assert(c.roundId() == beforeRoundId);
            assert(!c.isSelectionComplete(beforeRoundId));
        }
    }
}

