contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 tokenId, uint256 points) public payable {
        uint256 beforeTotal = c.totalPoints();
        uint256 beforeFighter = c.fighterPoints(tokenId);

        address expectedCaller = address(this);
        bool callerIsRankedBattle = expectedCaller == address(this);

        bool reverted;
        try c.addPoints(tokenId, points) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterTotal = c.totalPoints();
        uint256 afterFighter = c.fighterPoints(tokenId);

        assert(
            reverted
                ? (afterTotal == beforeTotal && afterFighter == beforeFighter && !callerIsRankedBattle)
                : (afterTotal == beforeTotal + points && afterFighter == beforeFighter + points)
        );
    }
}

contract InvMutTest {
