        uint256 beforeTotal = c.totalPoints();
        uint256 beforeFighter = c.fighterPoints(tokenId);

        bool reverted;
        bool success;
        try c.addPoints(tokenId, points) {
            reverted = false;
            success = true;
        } catch {
            reverted = true;
            success = false;
        }

        uint256 afterTotal = c.totalPoints();
        uint256 afterFighter = c.fighterPoints(tokenId);

        bool callerIsRankedBattle = false;

        if (reverted) {
            assert(!callerIsRankedBattle && afterTotal == beforeTotal && afterFighter == beforeFighter);
        } else {
            assert(success && afterTotal == beforeTotal + points && afterFighter == beforeFighter + points);
        }
    }
}

