contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 winId, uint256 pointAmount, address other) public {
        require(other != address(0) && uint32(c.numRoundsClaimed(address(this))) == 0);
        // add points to the fighter that will be selected
        c.addPoints(winId, pointAmount);
        // reset roundId so we can pick a winner for a known round
        uint256 roundBefore = c.roundId();
        uint256[] memory winners = new uint256[](1);
        winners[0] = winId;
        // pickWinner requires winnersPerPeriod == winners.length; default is 2, so update first
        c.updateWinnersPerPeriod(1);
        c.pickWinner(winners);
        uint256 roundAfter = c.roundId();
        require(roundAfter == roundBefore + 1);
        // snapshots before claim
        uint256 claimedBefore = uint32(c.numRoundsClaimed(address(this)));
        uint256 rewardsBefore = c.getUnclaimedRewards(address(this));
        // claim as this contract (which is the owner of winId in this setup because fresh c won't have fighters...)
        // Instead use try/catch to observe behavior; if not winner, it should revert nothing but mint nothing.
        bool reverted;
        string[] memory uris = new string[](1);
        string[] memory types = new string[](1);
        uint256[2][] memory attrs = new uint256[2][](1);
        uris[0] = "u";
        types[0] = "t";
        attrs[0] = [uint256(1), uint256(2)];
        try c.claimRewards(uris, types, attrs) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 claimedAfter = uint32(c.numRoundsClaimed(address(this)));
        uint256 rewardsAfter = c.getUnclaimedRewards(address(this));
        // GENERAL RULE: claimRewards must not mint for non-winners, and must mark the round claimed
        // If this contract is a winner (i.e., owns winId), rewardsBefore > 0 and a claim should succeed.
        // We assert a reachable general invariant:
        // - numRoundsClaimed increases by exactly 1 per unclaimed round (roundBefore was freshly added)
        // - getUnclaimedRewards goes to 0 + any rounds after
        assert(
            (rewardsBefore == 0 && rewardsAfter == 0 && claimedAfter == claimedBefore) ||
            (rewardsBefore > 0 && claimedAfter == claimedBefore + 1)
        );
    }
    receive() external payable {}
}

