            assert(reverted);
            assert(afterRoundId == beforeRoundId);
            assert(afterComplete == beforeComplete);
            assert(afterTotalPoints == beforeTotalPoints);
        } else if (reverted) {
            assert(afterRoundId == beforeRoundId);
            assert(afterComplete == beforeComplete);
            assert(afterTotalPoints == beforeTotalPoints);
        } else {
            assert(afterRoundId == beforeRoundId + 1);
            assert(afterComplete);
        }
    }
}

