        uint256 afterAddFighterPoints = c.getFighterPoints(tokenId + 1)[tokenId];

        assert(
            afterWinnersPerPeriod == newWinnersPerPeriod &&
            afterRound == (winners.length == beforeWinnersPerPeriod && beforeWinnersPerPeriod != 0 ? afterPickRound : afterRound) &&
            afterFighterPoints == beforeFighterPoints &&
            (reverted || afterUnclaimed <= beforeUnclaimed) &&
            numRoundsClaimed <= afterRound &&
            addPointsReverted &&
            afterAddFighterPoints == beforeFighterPoints &&
            afterAddTotalPoints == beforeTotalPoints &&
            beforeWinnersPerPeriod <= type(uint256).max
        );
    }
}

