contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 numWinners, uint256 roundBefore) public payable {
        require(true);

        uint256 winnersPerPeriodBefore = c.winnersPerPeriod();
        uint256 roundIdBefore = c.roundId();

        require(numWinners <= 8);
        uint256[] memory winners = new uint256[](numWinners);
        for (uint256 i = 0; i < numWinners; i++) {
            winners[i] = numWinners + i;
        }

        bool reverted;
        try c.pickWinner(winners) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool wasComplete = c.isSelectionComplete(roundIdBefore);
        uint256 roundIdAfter = c.roundId();
        uint256 winnersPerPeriodAfter = c.winnersPerPeriod();

        uint256 storedWinnerCount = 0;
        if (!reverted) {
            storedWinnerCount = c.winnerAddresses(roundIdBefore).length;
        }

        assert(
            reverted
                ? (numWinners != winnersPerPeriodBefore || wasComplete || roundIdAfter == roundIdBefore)
                : (numWinners == winnersPerPeriodBefore && !wasComplete && roundIdAfter == roundIdBefore + 1 && storedWinnerCount == numWinners)
        );
    }
}

